/*
 * High-performance portfolio calculations using C extension
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static double item_as_double(PyObject *item) {
    if (PyFloat_Check(item))
        return PyFloat_AS_DOUBLE(item);
    return PyFloat_AsDouble(item);
}

static PyObject* risk_from_buffers(const double *weights, const double *cov,
                                   npy_intp n) {
    double *temp = (double *)malloc((size_t)n * sizeof(double));
    if (temp == NULL) {
        PyErr_NoMemory();
        return NULL;
    }

    for (npy_intp i = 0; i < n; i++) {
        const double *row = cov + i * n;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; j++) {
            row_sum += row[j] * weights[j];
        }
        temp[i] = row_sum;
    }

    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; i++) {
        risk_squared += weights[i] * temp[i];
    }

    free(temp);
    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* risk_from_numpy(PyArrayObject *weights_array,
                                 PyArrayObject *cov_array) {
    if (PyArray_NDIM(weights_array) != 1 ||
        PyArray_TYPE(weights_array) != NPY_DOUBLE ||
        !PyArray_IS_C_CONTIGUOUS(weights_array)) {
        PyErr_SetString(PyExc_ValueError,
                        "weights must be a contiguous 1-D float64 array");
        return NULL;
    }
    if (PyArray_NDIM(cov_array) != 2 ||
        PyArray_TYPE(cov_array) != NPY_DOUBLE ||
        !PyArray_IS_C_CONTIGUOUS(cov_array)) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix must be a contiguous 2-D float64 array");
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(cov_array, 0) != n || PyArray_DIM(cov_array, 1) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix dimensions must match weights length");
        return NULL;
    }

    const double *weights = (const double *)PyArray_DATA(weights_array);
    const double *cov = (const double *)PyArray_DATA(cov_array);
    return risk_from_buffers(weights, cov, n);
}

static PyObject* risk_from_sequences(PyObject *weights_obj, PyObject *cov_obj) {
    PyObject *weights_seq = PySequence_Fast(weights_obj,
                                            "weights must be a sequence");
    if (weights_seq == NULL)
        return NULL;

    npy_intp n = PySequence_Fast_GET_SIZE(weights_seq);
    PyObject *cov_seq = PySequence_Fast(cov_obj,
                                        "cov_matrix must be a sequence");
    if (cov_seq == NULL) {
        Py_DECREF(weights_seq);
        return NULL;
    }

    if (PySequence_Fast_GET_SIZE(cov_seq) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix dimensions must match weights length");
        Py_DECREF(weights_seq);
        Py_DECREF(cov_seq);
        return NULL;
    }

    double *weights = (double *)malloc((size_t)n * sizeof(double));
    double *temp = (double *)malloc((size_t)n * sizeof(double));
    if (weights == NULL || temp == NULL) {
        free(weights);
        free(temp);
        Py_DECREF(weights_seq);
        Py_DECREF(cov_seq);
        return PyErr_NoMemory();
    }

    for (npy_intp i = 0; i < n; i++) {
        double v = item_as_double(PySequence_Fast_GET_ITEM(weights_seq, i));
        if (v == -1.0 && PyErr_Occurred()) {
            free(weights);
            free(temp);
            Py_DECREF(weights_seq);
            Py_DECREF(cov_seq);
            return NULL;
        }
        weights[i] = v;
    }

    for (npy_intp i = 0; i < n; i++) {
        PyObject *row_obj = PySequence_Fast_GET_ITEM(cov_seq, i);
        PyObject *row_seq;
        int owned = 0;

        if (PyList_Check(row_obj) || PyTuple_Check(row_obj)) {
            row_seq = row_obj;
        } else {
            row_seq = PySequence_Fast(row_obj, "each cov_matrix row must be a sequence");
            if (row_seq == NULL) {
                free(weights);
                free(temp);
                Py_DECREF(weights_seq);
                Py_DECREF(cov_seq);
                return NULL;
            }
            owned = 1;
        }

        if (PySequence_Fast_GET_SIZE(row_seq) != n) {
            PyErr_SetString(PyExc_ValueError,
                            "cov_matrix must be square and match weights length");
            if (owned)
                Py_DECREF(row_seq);
            free(weights);
            free(temp);
            Py_DECREF(weights_seq);
            Py_DECREF(cov_seq);
            return NULL;
        }

        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; j++) {
            double v = item_as_double(PySequence_Fast_GET_ITEM(row_seq, j));
            if (v == -1.0 && PyErr_Occurred()) {
                if (owned)
                    Py_DECREF(row_seq);
                free(weights);
                free(temp);
                Py_DECREF(weights_seq);
                Py_DECREF(cov_seq);
                return NULL;
            }
            row_sum += v * weights[j];
        }
        temp[i] = row_sum;

        if (owned)
            Py_DECREF(row_seq);
    }

    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; i++) {
        risk_squared += weights[i] * temp[i];
    }

    free(weights);
    free(temp);
    Py_DECREF(weights_seq);
    Py_DECREF(cov_seq);
    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    if (PyArray_Check(weights_obj) && PyArray_Check(cov_obj))
        return risk_from_numpy((PyArrayObject *)weights_obj,
                               (PyArrayObject *)cov_obj);

    return risk_from_sequences(weights_obj, cov_obj);
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    if (PyArray_Check(weights_obj) && PyArray_Check(returns_obj)) {
        PyArrayObject *weights_array = (PyArrayObject *)weights_obj;
        PyArrayObject *returns_array = (PyArrayObject *)returns_obj;

        if (PyArray_NDIM(weights_array) != 1 ||
            PyArray_TYPE(weights_array) != NPY_DOUBLE ||
            !PyArray_IS_C_CONTIGUOUS(weights_array)) {
            PyErr_SetString(PyExc_ValueError,
                            "weights must be a contiguous 1-D float64 array");
            return NULL;
        }
        if (PyArray_NDIM(returns_array) != 1 ||
            PyArray_TYPE(returns_array) != NPY_DOUBLE ||
            !PyArray_IS_C_CONTIGUOUS(returns_array)) {
            PyErr_SetString(PyExc_ValueError,
                            "expected_returns must be a contiguous 1-D float64 array");
            return NULL;
        }

        npy_intp n = PyArray_DIM(weights_array, 0);
        if (PyArray_DIM(returns_array, 0) != n) {
            PyErr_SetString(PyExc_ValueError, "array lengths must match");
            return NULL;
        }

        const double *weights = (const double *)PyArray_DATA(weights_array);
        const double *returns = (const double *)PyArray_DATA(returns_array);
        double total_return = 0.0;
        for (npy_intp i = 0; i < n; i++) {
            total_return += weights[i] * returns[i];
        }
        return PyFloat_FromDouble(total_return);
    }

    PyObject *weights_seq = PySequence_Fast(weights_obj,
                                            "weights must be a sequence");
    if (weights_seq == NULL)
        return NULL;
    PyObject *returns_seq = PySequence_Fast(returns_obj,
                                            "expected_returns must be a sequence");
    if (returns_seq == NULL) {
        Py_DECREF(weights_seq);
        return NULL;
    }

    npy_intp n = PySequence_Fast_GET_SIZE(weights_seq);
    if (PySequence_Fast_GET_SIZE(returns_seq) != n) {
        PyErr_SetString(PyExc_ValueError, "array lengths must match");
        Py_DECREF(weights_seq);
        Py_DECREF(returns_seq);
        return NULL;
    }

    double total_return = 0.0;
    for (npy_intp i = 0; i < n; i++) {
        double w = item_as_double(PySequence_Fast_GET_ITEM(weights_seq, i));
        double r = item_as_double(PySequence_Fast_GET_ITEM(returns_seq, i));
        if (PyErr_Occurred()) {
            Py_DECREF(weights_seq);
            Py_DECREF(returns_seq);
            return NULL;
        }
        total_return += w * r;
    }

    Py_DECREF(weights_seq);
    Py_DECREF(returns_seq);
    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
